WITH agg AS ( SELECT i.i_category, i.i_brand, sm.sm_type AS ship_mode_type, w.w_state, COUNT(*) AS return_cnt, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_amount) AS total_return_amount, AVG(cr.cr_return_quantity) AS avg_return_qty FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk WHERE cr.cr_returned_date_sk BETWEEN 20200101 AND 20201231 GROUP BY i.i_category, i.i_brand, sm.sm_type, w.w_state HAVING SUM(cr.cr_net_loss) > 0 ) SELECT i_category, i_brand, ship_mode_type, w_state, return_cnt, total_net_loss, total_return_amount, avg_return_qty, RANK() OVER (PARTITION BY w_state ORDER BY total_net_loss DESC) AS category_state_rank, CASE WHEN total_net_loss > 20000 THEN 'Critical' WHEN total_net_loss > 10000 THEN 'High' WHEN total_net_loss > 5000 THEN 'Medium' ELSE 'Low' END AS loss_severity FROM agg ORDER BY w_state, total_net_loss DESC LIMIT 20
